/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type GraphState =
  /** A graph is loaded and the updater is idle. */
  | 'LOADED'
  /** No graph is loaded. */
  | 'UNAVAILABLE'
  /** A graph is loaded and the updater is working on a new one. */
  | 'UPDATING';

/** Two node ids: a dependency's source and target, each standing for its subtree. */
export type NodePair = {
  /** The depending end. */
  sourceId: string | number;
  /** The end depended upon. */
  targetId: string | number;
};

/** One side of a `filteredDependencies` selection. */
export type NodeSelection = {
  /** The selected nodes; each stands for its subtree. */
  selectedNodeIds: Array<string | number>;
  /** Which side of the dependencies the nodes select. */
  selectedNodesType: NodeType;
};

/** Which side of a dependency a node is on. */
export type NodeType =
  /** The depending end. */
  | 'SOURCE'
  /** The end depended upon. */
  | 'TARGET';

